from pathlib import Path
import re
src=Path(r'E:\xx\Rods\work\make_prototype.cjs').read_text(encoding='utf-8')
src=src.replace('prototype-v03','prototype-v04').replace('V0.3','V0.4')
score='''function scores(me){let all=[me,...rivals],total=[0,0,0,0],detail=[]; for(let j=0;j<6;j++){let vals=all.map(a=>a[j]),ss=[0,0,0,0];let unique=vals.map((v,i)=>({v,i})).filter(x=>x.v>0&&vals.filter(v=>v===x.v).length===1).sort((a,b)=>b.v-a.v);unique.slice(0,2).forEach((x,k)=>ss[x.i]=reward[j][k]);ss.forEach((x,i)=>total[i]+=x);detail.push(ss);}return {total,detail};}'''
src=re.sub(r'function scores\(me\).*?\n',lambda _:score+'\n',src,count=1)
src=src.replace('const me=[3,5,0,0,3,2],s=scores(me)','const me=[4,5,4,0,0,0],s=scores(me)')
src=src.replace('风区、方区并列分奖，最终领先 1 分。','风、花、雪各得第一，最终领先 2 分。').replace('示例结算 · 并列规则沿用待确认的均分方案','同筹力抵消后重新排名 · 总分并列最高也通关')
src=src.replace('第 06 屏为独立结算示例 · 并列计分与广告方案仍待决策','结算按同筹力抵消计算 · 金币单价与余额仅为界面示例，待配置')
insert=r'''
function paid(mode){let coin=mode==='coin';return play('selected').replace('残局挑战',coin?'金币 150':'金币 0').replace('重投手中全部 <span>剩余 2 次</span>',coin?'金币重投全部 <span>消耗 100 金币</span>':'看广告重投全部 <span>完成后重投 1 次</span>').replace('已落区不参与重投 · 免费次数按整局计算',coin?'免费 0 次 · 金币充足，优先使用金币':'免费 0 次 · 金币不足，观看广告后重投');}
function failure(){let me=[3,5,0,0,3,2],s=scores(me),ranked=['你','电脑甲','电脑乙','电脑丙'].map((n,i)=>({n,i,v:s.total[i]})).sort((a,b)=>b.v-a.v);return `${nav()}<div class="content result"><div class="victorymark">再</div><div class="resulttag">本局未通关</div><h1>差一步破局</h1><p>重开一局，或取回 6 点筹力再试</p><div class="bigscore">${s.total[0]}<small>你的最终胜分</small></div><div class="places">${ranked.map((r,k)=>`<div><span>${k+1}</span><b>${r.n}</b><em>${r.v}</em></div>`).join('')}</div><div class="review"><b>同筹力抵消，名次重新计算</b><span>风区你与甲同为3点，均不计分；丙递补第一。</span></div><div class="reviveintro"><b>复活取回 6 点筹力</b><p>自己选择算筹，可跨区、可拆组。<br>看完一次广告后重新投掷，次数不限。</p></div><button class="primary">免费重开</button><button class="secondary">选择 6 点筹力复活</button><div class="smallnote">先选算筹，再看广告 · 失败后可再次选择</div></div>${foot()}`;}
function revive(){let dice=[{v:3,f:1},{v:2,f:0},{v:2,f:4},{v:1,f:1},{v:1,f:1},{v:1,f:0},{v:1,f:4},{v:1,f:5},{v:1,f:5}];return `${nav()}<div class="content revive"><div class="level"><span>复活选择</span><b>全部为你已落区的算筹</b></div><h1>取回六点，再掷一局</h1><p>点击算筹自由选择，可跨区域拆组。</p><div class="selectioncount"><b>6 <i>/ 6</i></b><span>已选筹力 · 共 3 枚</span></div><div class="tray">${dice.map((d,i)=>die(d,[0,1,3].includes(i))).join('')}</div><div class="hint highlight"><b>已选：花3 ＋ 风2 ＋ 花1 ＝ 6点</b><span>未选的6枚保留原位置，共7点筹力</span></div><div class="reviveintro"><b>广告完成后才撤回</b><p>选中的3枚返回手中，整批重新投掷。<br>免费重投余额保留，已消耗次数不恢复。</p></div><button class="primary">看广告并取回 6 点筹力</button><button class="secondary" style="margin-top:8px">取消选择，返回失败页</button><div class="smallnote">不足或超过6点时无法确认 · 复活次数不限</div></div>${foot()}`;}
'''
src=src.replace('const screens=[',insert+'\nconst screens=[')
src=src.replace("['result','06 结算反馈','胜分与筹力分开，逐区解释结果',result()]];","['result','06 结算反馈','同筹力抵消；总分并列最高也通关',result()],['coin','07 金币重投','免费用尽后扣金币，不开放广告绕过',paid('coin')],['ad','08 广告重投','金币不足后开放广告，单局不限次数',paid('ad')],['failure','09 失败选择','玩家自主选择免费重开或广告复活',failure()],['revive','10 复活选筹','自由选取恰好6点，可跨区拆组',revive()]];")
src=src.replace('</style>', '.revive h1{font-size:25px;margin:24px 0 10px}.revive>p{font-size:12px;color:#7b8472}.selectioncount{text-align:center;padding:16px 0 20px}.selectioncount b{display:block;font:46px Georgia}.selectioncount i{font-size:24px;color:#929d86;font-style:normal}.selectioncount span{font-size:11px;color:#79896e}.reviveintro{text-align:left;border-top:1px solid #d5decc;padding:16px 0;margin:9px 0;font-size:12px;line-height:1.8}.reviveintro p{color:#7b8871;margin:5px 0 0;font-size:11px}.revive .secondary{margin-top:8px}</style>',1)
src=src.replace("await page.screenshot({path:path.join(out,'六面算筹原型总览.png'),fullPage:true});", "await page.locator('.frame').evaluateAll(es=>es.forEach((e,i)=>{if(i>=6)e.style.display='none'}));await page.screenshot({path:path.join(out,'六面算筹原型总览.png'),fullPage:true});await page.locator('.frame').evaluateAll(es=>es.forEach((e,i)=>e.style.display=i<6?'none':''));await page.screenshot({path:path.join(out,'重投与复活原型.png'),fullPage:true});await page.locator('.frame').evaluateAll(es=>es.forEach(e=>e.style.display=''));" )
Path(r'E:\xx\Rods\work\make_prototype_v04.cjs').write_text(src,encoding='utf-8')
